        for reference in &mut refs {
            let verification = verify_stage_ref(store, reference);
            reference.status = Some(verification.status.clone());
            reference.actual_cid = verification.actual_cid.clone();
            reference.message = verification.message.clone();
            ref_verify.push(verification);
        }
    }
    let stage_status = stage_status(value)?.to_owned();
    let verdict_status = stage_verdict_status(value)?.to_owned();
    let acceptance = if verify_acceptance {
        let evidence_refs = refs
            .iter()
            .map(|reference| StageEvidenceRef {
                role: reference.role.clone(),
                cid: reference.cid.clone(),
            })
            .collect::<Vec<_>>();
        Some(match acceptance_cache {
            Some(cache) => verify_stage_acceptance_cached(
                store,
                &stage_status,
                &verdict_status,
                &evidence_refs,
                cache,
            )?,
